class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late Future<void> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  String _currentQuery = '';

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitialData() async {
    final currencyRepository = context.read<CurrencyRepository>();

    final page = await currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD', pageSize: 20));
    _allCurrencies = page.items;
    _currentPage = page.page;
    _hasMore = page.hasMore;
    _filteredCurrenciesNotifier = ValueNotifier(_allCurrencies);

    _fadeController.forward(); // запускаем анимацию

    await currencyRepository.saveCurrencyList(_allCurrencies);
  }

  Future<void> _loadNextPage() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() {
      _isLoadingMore = true;
    });

    final currencyRepository = context.read<CurrencyRepository>();
    final nextPage = await currencyRepository.fetchRates(
      CurrencyPageRequest(base: 'USD', page: _currentPage + 1, pageSize: 20),
    );

    if (mounted) {
      setState(() {
        _allCurrencies.addAll(nextPage.items);
        _currentPage = nextPage.page;
        _hasMore = nextPage.hasMore;

        // Re-apply filter if there's a search query
        if (_currentQuery.isNotEmpty) {
          _filteredCurrenciesNotifier.value = _filterItems(_allCurrencies, _currentQuery);
        } else {
          _filteredCurrenciesNotifier.value = List.unmodifiable(_allCurrencies);
        }

        _isLoadingMore = false;
      });
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (mounted && !_currencyListFuture.isCompleted) {
      // Already loading
    }
  }

  List<CurrencyModel> _filterItems(List<CurrencyModel> items, String query) {
    final String lowerQuery = query.toLowerCase();
    return items.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    }).toList(growable: false);
  }

  void _filterCurrencies(String query) {
    _currentQuery = query;
    _filteredCurrenciesNotifier.value = _filterItems(_allCurrencies, query);
  }

